#!/usr/bin/env python3
"""
Pages Batch 24 (Canvases 151-155, pp. 114-118) for Wellcome MS.244.
Covers the main medical and surgical compendium on De morbo Gallico (the French Pox / syphilis),
the Small Pox, sore eyes, and bruises/contusions:
  - Canvas 151 (p. 114 / Cxiij): Pox (Sanativum morbi neopolut, internal & external pox cures, Dr. Anthony's grey ointment, guaiacum decoction, mercurial ointments & washes)
  - Canvas 152 (p. 115 / Cxv): Pox (ointments for pox and ache, mouthwash, weak & strong purges, Aqua destillata ad morbum gallicum, Henry Dineley's April 1617 note, white vitriol & quicksilver powder, Master Low to Bolton's sarsaparilla diet drink)
  - Canvas 153 (p. 116 / Cxvj): Pox & Small Pox (1619 direct cure: turbith mineral & pills, salivation regimen, 1618 unguentum & sweating/anointing instructions, marigold & red fennel posset for small pox)
  - Canvas 154 (p. 117): Pox, Small Pox, Sore Eyes & Inward Bruise (Clusius in Monardes p. 41 sarsaparilla powder & water, Leonardo Fioravanti's Unguento Magno, small pox & measles remedies, sore eyes butter-egg ointment, pock-hole almond cream, sweet trefoil & wormwood/linseed poultice for inward bruise)
  - Canvas 155 (p. 118 / Cxviij): Bruise (various poultices, elder-flower oil, searcloth, water betony ointment, mullein juice, Emplastrum omnibus contusionibus with 'Empl[astrum] homini Dingley' cross-reference, sweet trefoil balsam oil, dulcamara & elder bath)
"""


def make_lines(prefix, canvas_num, col_id, ulx, uly, lrx, lry, line_tuples):
    n = len(line_tuples)
    step = (lry - uly) / max(1, n)
    img_svc = f"https://iiif.wellcomecollection.org/image/b19608652_MS_244_{canvas_num:04d}.JP2"
    canvas_uri = f"https://iiif.wellcomecollection.org/presentation/b19608652/canvases/b19608652_MS_244_{canvas_num:04d}.JP2"
    out = []
    for idx, (lno, ltype, orig_text, en_text, note) in enumerate(line_tuples):
        y0 = int(round(uly + idx * step))
        y1 = int(round(uly + (idx + 1) * step))
        w = lrx - ulx
        h = y1 - y0
        xywh = f"{ulx},{y0},{w},{h}"
        line_id = f"{prefix}_{col_id}_l{lno:02d}" if isinstance(lno, int) else f"{prefix}_{col_id}_{lno}"
        out.append({
            "line_id": line_id,
            "line_num": str(lno),
            "line_type": ltype,
            "ulx": ulx,
            "uly": y0,
            "lrx": lrx,
            "lry": y1,
            "xywh": xywh,
            "iiif_canvas_xywh": f"{canvas_uri}#xywh={xywh}",
            "iiif_image_crop": f"{img_svc}/{xywh}/full/0/default.jpg",
            "orig": orig_text,
            "en": en_text,
            "note": note,
        })
    return out


